/**
 * Pure generator: tokens.ts -> CSS text. Used by scripts/build-tokens.ts (writes the files) and
 * scripts/contrast-check.ts (verifies they are up to date).
 */
import { VIBES, type Vibe } from "./config";
import { ART_GRADIENTS, PALETTE_KEYS, SHAPE_KEYS, base, resolveTokens, vibes } from "./tokens";

const HEADER =
  "/* GENERATED by scripts/build-tokens.ts from src/features/vibe/tokens.ts. Do not edit by hand. */\n";

function declarations(entries: ReadonlyArray<readonly [string, string]>): string {
  return entries.map(([k, v]) => `  --${k}: ${v};`).join("\n");
}

/**
 * Visibility flags for VibeText / HandButton. Custom properties inherit from the NEAREST `[data-vibe]`
 * ancestor, which is what makes nested VibeScopes show the right copy variant.
 * `contents` = shown (the wrapper span generates no box), `none` = hidden.
 */
function flags(active: Vibe | null): string {
  return declarations(VIBES.map((v) => [`dv-${v}`, v === active ? "contents" : "none"] as const));
}

/** Per-vibe product-art gradient stops: global, so a tile keeps its product's colours under any active theme. */
function artStops(): string {
  return declarations(
    VIBES.flatMap((v) => [
      [`art-${v}-a`, ART_GRADIENTS[v][0]] as const,
      [`art-${v}-b`, ART_GRADIENTS[v][1]] as const,
    ]),
  );
}

function vibeBlock(vibe: Vibe): string {
  const resolved = resolveTokens(vibe);
  const palette = PALETTE_KEYS.map((k) => [k, resolved.palette[k]] as const);
  const shape = SHAPE_KEYS.map((k) => [k, resolved.shape[k]] as const);
  return [
    `[data-vibe="${vibe}"] {`,
    declarations(palette),
    "",
    declarations(shape),
    "",
    flags(vibe),
    "}",
  ].join("\n");
}

export function generateTokenCss(): Record<string, string> {
  const files: Record<string, string> = {};

  files["base.css"] = [
    HEADER,
    ":root {",
    declarations(PALETTE_KEYS.map((k) => [k, base.palette[k]] as const)),
    "",
    declarations(SHAPE_KEYS.map((k) => [k, base.shape[k]] as const)),
    "",
    flags(null),
    "",
    artStops(),
    "}",
    "",
  ].join("\n");

  for (const vibe of VIBES) {
    files[`${vibe}.css`] = [HEADER, vibeBlock(vibe), ""].join("\n");
  }

  // Must be imported AFTER every vibe file: on an element carrying both attributes, equal specificity
  // plus source order lets the buy reset win. A nested [data-vibe] on a DESCENDANT still wins because it
  // redeclares the variables on its own element.
  files["buy.css"] = [
    HEADER,
    "/* Buy scope: palette still comes from the active vibe; shape/type/texture reset to base. */",
    '[data-vibe-scope="buy"] {',
    declarations(SHAPE_KEYS.map((k) => [k, base.shape[k]] as const)),
    "}",
    "",
  ].join("\n");

  // Keep `vibes` referenced so a vibe missing from tokens.ts is a type error here too.
  void vibes;
  return files;
}
